CREATE TABLE users (
 id uuid PRIMARY KEY, email varchar(200) NOT NULL UNIQUE, name varchar(120) NOT NULL,
 password_hash text NOT NULL, role varchar(16) NOT NULL CHECK(role IN ('manager','ctv')),
 active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true,
 failed_attempts int NOT NULL DEFAULT 0, locked_until timestamptz,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL);
CREATE TABLE scents (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, meaning text NOT NULL, top_notes text NOT NULL, middle_notes text NOT NULL, base_notes text NOT NULL, ritual text NOT NULL);
CREATE TABLE products (id uuid PRIMARY KEY, sku varchar(50) NOT NULL UNIQUE, name varchar(180) NOT NULL, scent_id uuid REFERENCES scents(id), description text NOT NULL DEFAULT '', unit varchar(30) NOT NULL DEFAULT 'lọ', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_images (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), object_key text NOT NULL UNIQUE, caption text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE prices (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), channel varchar(16) NOT NULL CHECK(channel IN ('retail','wholesale','b2b')), unit_price numeric(15,0) NOT NULL CHECK(unit_price>0), commission_rate numeric(5,2) NOT NULL CHECK(commission_rate BETWEEN 0 AND 100), min_qty int NOT NULL CHECK(min_qty>0), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,channel));
CREATE TABLE customers (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name varchar(180) NOT NULL, phone varchar(40) NOT NULL DEFAULT '', email varchar(200) NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id uuid PRIMARY KEY, code varchar(32) NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES users(id), customer_id uuid NOT NULL REFERENCES customers(id), customer_snapshot jsonb NOT NULL, channel varchar(16) NOT NULL, status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','shipping','completed','cancelled','returned')), subtotal numeric(15,0) NOT NULL, shipping numeric(15,0) NOT NULL DEFAULT 0 CHECK(shipping>=0), paid numeric(15,0) NOT NULL DEFAULT 0 CHECK(paid>=0), commission_total numeric(15,0) NOT NULL DEFAULT 0, note text NOT NULL DEFAULT '', version int NOT NULL DEFAULT 1, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(paid<=subtotal+shipping));
CREATE TABLE order_lines (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), product_id uuid NOT NULL REFERENCES products(id), sku text NOT NULL, product_name text NOT NULL, unit text NOT NULL, qty int NOT NULL CHECK(qty>0), unit_price numeric(15,0) NOT NULL CHECK(unit_price>0), commission_rate numeric(5,2) NOT NULL CHECK(commission_rate BETWEEN 0 AND 100), amount numeric(15,0) NOT NULL, commission numeric(15,0) NOT NULL);
CREATE TABLE quotes (id uuid PRIMARY KEY, code varchar(32) NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES users(id), customer_id uuid NOT NULL REFERENCES customers(id), customer_snapshot jsonb NOT NULL, channel varchar(16) NOT NULL, status varchar(16) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','rejected')), subtotal numeric(15,0) NOT NULL, shipping numeric(15,0) NOT NULL DEFAULT 0 CHECK(shipping>=0), valid_until date NOT NULL, note text NOT NULL DEFAULT '', terms text NOT NULL, seller_snapshot jsonb NOT NULL, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quote_lines (id uuid PRIMARY KEY, quote_id uuid NOT NULL REFERENCES quotes(id), product_id uuid NOT NULL REFERENCES products(id), sku text NOT NULL, product_name text NOT NULL, unit text NOT NULL, qty int NOT NULL CHECK(qty>0), unit_price numeric(15,0) NOT NULL CHECK(unit_price>0), amount numeric(15,0) NOT NULL);
CREATE TABLE commissions (id uuid PRIMARY KEY, order_id uuid NOT NULL UNIQUE REFERENCES orders(id), user_id uuid NOT NULL REFERENCES users(id), amount numeric(15,0) NOT NULL CHECK(amount>=0), status varchar(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','paid','void')), payment_reference text NOT NULL DEFAULT '', approved_by uuid REFERENCES users(id), paid_at timestamptz, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, entity_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings (key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE order_events (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), actor_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_owner_date ON orders(owner_id,created_at DESC);
CREATE INDEX quotes_owner_date ON quotes(owner_id,created_at DESC);
CREATE INDEX customers_owner ON customers(owner_id);
CREATE INDEX audit_date ON audit_logs(created_at DESC);
CREATE INDEX commissions_user ON commissions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
